/**
 * The caller's address behind the proxies this service's platform declares, and
 * the anonymous rate-limit key.
 *
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 *
 * A forwarded header (`X-Forwarded-For`) or the framework header the system gateway
 * overwrites (`X-CruftFree-Client-Address`) is read only when a declared,
 * vendor-documented proxy wrote it and the request provably came through that proxy; every other case,
 * and every failure, uses the connection peer, which the caller cannot choose. The
 * resolution fails closed: it may be too coarse (a proxy's address), never forgeable.
 * Express's own `trust proxy` is never set, so `req.ip` is never consulted.
 *
 * The algorithm, identical on every language:
 *
 * 1. `peer` is the connection's remote address, canonicalized; no peer is `null`.
 * 2. `transport_peer`: return `peer`.
 * 3. `forwarded_for`: return `peer` unless the request came through the declared proxy
 *    (`peer` in a trusted network, or the platform front end is the only ingress --
 *    then the header is read even with no peer); take the `X-Forwarded-For` entry
 *    `trustedHops` from the right, dropping a port the proxy appended to it; a short
 *    list or an invalid entry logs a reason code and returns `peer`.
 * 4. `gateway_asserted`: return `peer` unless the request is verified (when the
 *    policy requires the trusted-caller stage); read the single asserted-header value:
 *    none returns `peer` (an east-west call), a duplicate or invalid value logs a
 *    reason code and returns `peer`.
 * 5. Canonical form: a bare IPv4 or IPv6 literal with no port, brackets or zone; IPv6
 *    lowercase and compressed; an IPv4-mapped IPv6 address becomes its IPv4 address;
 *    anything else is invalid.
 *
 * A service's own listener resolves under `CLIENT_ADDRESS_POLICY`. A serverless endpoint
 * hosted off the container runtime resolves under `SERVERLESS_CLIENT_ADDRESS_POLICY`,
 * with the address its host reports as the peer: the gateway header the listener's
 * policy may trust is never written on a serverless invocation.
 *
 * Logs carry the reason code and the kind only, never a header value or an address.
 */
import { Logger } from '@nestjs/common';
import type { IncomingMessage } from 'node:http';
import { BlockList, isIP } from 'node:net';
import { isTrustedCaller } from '../auth/trusted-caller.guard';

export const KIND_TRANSPORT_PEER = "transport_peer";
export const KIND_FORWARDED_FOR = "forwarded_for";
export const KIND_GATEWAY_ASSERTED = "gateway_asserted";

/** The facts one resolution reads, baked at generation time. */
interface ClientAddressPolicy {
  readonly kind: string;
  readonly trustedHops: number;
  readonly trustedPeerNetworks: readonly string[];
  readonly peerIsPlatformFrontEnd: boolean;
  readonly assertedHeader: string;
  readonly requiresTrustedCaller: boolean;
  readonly ipv6RateLimitPrefixLength: number;
}

/** What one request offers the resolution: its peer, its header lines and its verified mark. */
interface ResolutionInput {
  /** The remote address as the server or serverless host reports it; absent when none. */
  readonly remote: string | undefined;
  /** Every value of header `name` (lower-case), one entry per header line, in order. */
  readonly headerValues: (name: string) => readonly string[];
  /** Whether the trusted-caller stage verified this request. */
  readonly trustedCallerVerified: boolean;
}

/** The facts this service's platform declares for its own listener. */
export const CLIENT_ADDRESS_POLICY: ClientAddressPolicy = {"assertedHeader": "x-cruftfree-client-address", "ipv6RateLimitPrefixLength": 64, "kind": "gateway_asserted", "peerIsPlatformFrontEnd": false, "requiresTrustedCaller": true, "trustedHops": 0, "trustedPeerNetworks": []};

const REASON_FORWARDED_SHORT = "client_address_forwarded_short";
const REASON_FORWARDED_INVALID = "client_address_forwarded_invalid";
const REASON_ASSERTION_INVALID = "client_address_assertion_invalid";

const FORWARDED_FOR_HEADER = 'x-forwarded-for';
const IPV4_MAPPED_IPV6 = /^::ffff:([0-9a-f]{1,4}):([0-9a-f]{1,4})$/;
const DIGITS = /^[0-9]+$/;
const UNKNOWN_CLIENT_KEY = 'ip:unknown';
const IPV6_GROUP_COUNT = 8;
const IPV6_GROUP_BITS = 16;
const IPV6_GROUP_MASK = 0xffff;
const BYTE_MASK = 0xff;
const BYTE_BITS = 8;

const logger = new Logger('ClientAddress');

/** Each baked policy's trusted networks, built once per policy. */
const TRUSTED_PEERS = new WeakMap<ClientAddressPolicy, BlockList>();

function trustedPeers(policy: ClientAddressPolicy): BlockList {
  const cached = TRUSTED_PEERS.get(policy);
  if (cached !== undefined) {
    return cached;
  }
  const peers = new BlockList();
  for (const network of policy.trustedPeerNetworks) {
    const [base, prefix] = network.split('/');
    peers.addSubnet(base, Number(prefix), base.includes(':') ? 'ipv6' : 'ipv4');
  }
  TRUSTED_PEERS.set(policy, peers);
  return peers;
}

function ipv6Hostname(text: string): string | null {
  try {
    return new URL(`http://[${text}]/`).hostname.slice(1, -1);
  } catch {
    return null;
  }
}

function canonicalIpv6(text: string): string | null {
  const serialized = ipv6Hostname(text);
  if (serialized === null) {
    return null;
  }
  const mapped = IPV4_MAPPED_IPV6.exec(serialized);
  if (mapped === null) {
    return serialized;
  }
  const high = parseInt(mapped[1], 16);
  const low = parseInt(mapped[2], 16);
  return `${high >> BYTE_BITS}.${high & BYTE_MASK}.${low >> BYTE_BITS}.${low & BYTE_MASK}`;
}

/** The canonical form of `value`, or `null` when it is not a bare IPv4 or IPv6 literal. */
export function canonicalAddress(value: string): string | null {
  const text = value.trim();
  if (text === '' || text.includes('%')) {
    return null;
  }
  const family = isIP(text);
  if (family === 4) {
    return text;
  }
  return family === 6 ? canonicalIpv6(text) : null;
}

/**
 * The canonical address of one `X-Forwarded-For` entry, or `null` when invalid. A proxy
 * may append the peer it saw with its port (`203.0.113.7:51234`, `[2001:db8::1]:51234`);
 * the port is dropped before the address is canonicalized.
 */
export function forwardedEntryAddress(entry: string): string | null {
  const text = entry.trim();
  if (text.startsWith('[')) {
    const close = text.indexOf(']');
    if (close < 0) {
      return null;
    }
    const port = text.slice(close + 1);
    if (port !== '' && !(port.startsWith(':') && DIGITS.test(port.slice(1)))) {
      return null;
    }
    return canonicalAddress(text.slice(1, close));
  }
  const colon = text.indexOf(':');
  if (colon >= 0 && text.indexOf(':', colon + 1) < 0) {
    return DIGITS.test(text.slice(colon + 1)) ? canonicalAddress(text.slice(0, colon)) : null;
  }
  return canonicalAddress(text);
}

function logFallback(policy: ClientAddressPolicy, reason: string, level: 'log' | 'warn'): void {
  logger[level](`client_address_fallback reason=${reason} kind=${policy.kind}`);
}

function peerIsInTrustedNetworks(policy: ClientAddressPolicy, peer: string): boolean {
  return trustedPeers(policy).check(peer, peer.includes(':') ? 'ipv6' : 'ipv4');
}

function fromForwardedFor(
  policy: ClientAddressPolicy,
  input: ResolutionInput,
  peer: string | null,
): string | null {
  // With the platform front end as the only ingress the header is the front end's
  // whatever the peer, so a host that hands over no connection peer still reads it.
  if (peer === null && !policy.peerIsPlatformFrontEnd) {
    return null;
  }
  if (peer !== null && policy.trustedPeerNetworks.length > 0 && !peerIsInTrustedNetworks(policy, peer)) {
    return peer;
  }
  const entries = input.headerValues(FORWARDED_FOR_HEADER).flatMap((value) =>
    value.split(',').map((entry) => entry.trim()),
  );
  if (entries.length < policy.trustedHops) {
    // A request through the declared peer with no entry is a platform probe or a
    // direct call: informational, never a security event.
    logFallback(policy, REASON_FORWARDED_SHORT, 'log');
    return peer;
  }
  const forwarded = forwardedEntryAddress(entries[entries.length - policy.trustedHops]);
  if (forwarded === null) {
    logFallback(policy, REASON_FORWARDED_INVALID, 'warn');
    return peer;
  }
  return forwarded;
}

function fromAssertion(
  policy: ClientAddressPolicy,
  input: ResolutionInput,
  peer: string | null,
): string | null {
  if (policy.requiresTrustedCaller && !input.trustedCallerVerified) {
    return peer;
  }
  const values = input.headerValues(policy.assertedHeader);
  if (values.length === 0) {
    return peer;
  }
  if (values.length > 1) {
    logFallback(policy, REASON_ASSERTION_INVALID, 'warn');
    return peer;
  }
  const asserted = canonicalAddress(values[0]);
  if (asserted === null) {
    logFallback(policy, REASON_ASSERTION_INVALID, 'warn');
    return peer;
  }
  return asserted;
}

/** The caller's canonical address for `input` under `policy`, or `null` with no peer. */
function resolveClientAddress(policy: ClientAddressPolicy, input: ResolutionInput): string | null {
  const peer = input.remote === undefined ? null : canonicalAddress(input.remote);
  if (policy.kind === KIND_TRANSPORT_PEER) {
    return peer;
  }
  if (policy.kind === KIND_FORWARDED_FOR) {
    return fromForwardedFor(policy, input, peer);
  }
  if (policy.kind === KIND_GATEWAY_ASSERTED) {
    return fromAssertion(policy, input, peer);
  }
  throw new Error(
    `Unknown client address kind '${policy.kind}'. Valid kinds: ${KIND_TRANSPORT_PEER}, ` +
      `${KIND_FORWARDED_FOR}, ${KIND_GATEWAY_ASSERTED}.`,
  );
}

function rawHeaderValues(req: IncomingMessage, name: string): string[] {
  const values: string[] = [];
  const raw = req.rawHeaders;
  for (let index = 0; index + 1 < raw.length; index += 2) {
    if (raw[index].toLowerCase() === name) {
      values.push(raw[index + 1]);
    }
  }
  return values;
}

/**
 * The caller's canonical address for `req` under this service's listener policy, or
 * `null` when the connection reports no peer.
 */
export function clientAddress(req: IncomingMessage): string | null {
  return resolveClientAddress(CLIENT_ADDRESS_POLICY, {
    remote: req.socket?.remoteAddress,
    headerValues: (name) => rawHeaderValues(req, name),
    trustedCallerVerified: isTrustedCaller(req),
  });
}

function expandIpv6(address: string): number[] {
  const [head, tail] = address.split('::');
  const headGroups = head === '' ? [] : head.split(':');
  const tailGroups = tail === undefined || tail === '' ? [] : tail.split(':');
  const missing = IPV6_GROUP_COUNT - headGroups.length - tailGroups.length;
  return [...headGroups, ...new Array<string>(missing).fill('0'), ...tailGroups].map((group) =>
    parseInt(group, 16),
  );
}

function ipv6Network(address: string, prefixLength: number): string {
  const masked = expandIpv6(address).map((group, index) => {
    const kept = Math.min(Math.max(prefixLength - index * IPV6_GROUP_BITS, 0), IPV6_GROUP_BITS);
    return kept === 0 ? 0 : group & (IPV6_GROUP_MASK << (IPV6_GROUP_BITS - kept)) & IPV6_GROUP_MASK;
  });
  const serialized = ipv6Hostname(masked.map((group) => group.toString(16)).join(':'));
  if (serialized === null) {
    throw new Error(`Cannot serialize the IPv6 network of a canonical address (prefix ${prefixLength}).`);
  }
  return `${serialized}/${prefixLength}`;
}

/**
 * The anonymous rate-limit key: `ip:<IPv4>`, `ip:<IPv6 network>` or `ip:unknown`. An
 * IPv6 caller is keyed by its network of the policy's prefix length, so one holder of
 * a /64 cannot rotate buckets across it.
 */
export function clientRateLimitKey(address: string | null): string {
  if (address === null) {
    return UNKNOWN_CLIENT_KEY;
  }
  if (!address.includes(':')) {
    return `ip:${address}`;
  }
  return `ip:${ipv6Network(address, CLIENT_ADDRESS_POLICY.ipv6RateLimitPrefixLength)}`;
}
